WITH ranked AS (
  SELECT u.id, u.name, ROW_NUMBER() OVER (PARTITION BY u.team ORDER BY u.score DESC) AS rank
  FROM users AS u WHERE u.active = TRUE AND u.score >= 1.5
)
SELECT id, name FROM ranked WHERE rank = 1 ORDER BY name;
CREATE TABLE events (id BIGINT PRIMARY KEY, payload JSONB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
